from __future__ import annotations

import html
import json
from datetime import datetime, timezone

from . import __version__
from .evidence import HASH_LIMITATION
from .graph.builder import TemporalGraph

DISCLAIMER = (
    "Generated by AttackGraph Lens from the ingested telemetry only. Graph relationships show that interactions "
    "occurred; they do not prove compromise. Priority scores are heuristic triage rankings, not probabilities. "
    "Conclusions must be confirmed by an analyst."
)


def incident_report(g: TemporalGraph, incident: dict, files: list[dict], settings: dict) -> dict:
    events = []
    for uid in incident["supporting_events"]:
        ev = g.events.get(uid)
        if ev:
            events.append({"uid": uid, "timestamp": ev.timestamp.isoformat(), "source_system": ev.source_system,
                           "source_file": ev.source_file, "source_row": ev.source_row, "category": ev.category,
                           "raw": ev.raw})
    used_files = sorted({e["source_file"] for e in events})
    return {
        "report_type": "AttackGraph Lens incident report",
        "tool_version": __version__,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "incident": incident,
        "evidence_records": events,
        "source_files": [{"file_name": f["file_name"], "sha256": f["sha256"], "source_system": f["source_system"]}
                         for f in files if f["file_name"] in used_files],
        "analysis_settings": settings,
        "disclaimer": DISCLAIMER,
        "hash_limitation": HASH_LIMITATION,
    }


def _md_escape(s: str) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def to_markdown(rep: dict) -> str:
    inc = rep["incident"]
    out = [f"# Incident report: {inc['id']}: {inc['title']}", "",
           f"*Generated {rep['generated_at']} by AttackGraph Lens {rep['tool_version']}*", "",
           f"> {DISCLAIMER}", "",
           "## Summary", "",
           f"- **Priority:** {inc['priority']} ({inc['score']} / 100)",
           f"- **Window:** {inc['start']} → {inc['end']}",
           f"- **Identities:** {', '.join(inc['identities']) or '-'}",
           f"- **Affected assets:** {', '.join(inc['affected_assets']) or '-'}",
           f"- **Independent evidence sources:** {inc['independent_sources']} ({', '.join(inc['evidence_sources'])})",
           ""]
    out += [f"- {line}" for line in inc["explanation"]] + [""]
    out += ["## Priority breakdown", "", "| Component | Value | Weight | Contribution | Basis |", "|---|---|---|---|---|"]
    for b in inc["breakdown"]:
        out.append(f"| {b['label']} | {b['value']} | {b['weight']} | {b['contribution']} | {_md_escape(b['explanation'])} |")
    out += ["", f"*{inc['disclaimer']}*", ""]
    hyp = inc.get("hypothesis")
    if hyp:
        out += ["## Attack-path hypothesis", "", "`" + " → ".join(hyp["nodes"]) + "`", ""]
        out += ["| # | Time (UTC) | Step | Evidence | Source | Basis | Suspicion |", "|---|---|---|---|---|---|---|"]
        for i, s in enumerate(hyp["steps"], 1):
            out.append(f"| {i} | {s['timestamp']} | {_md_escape(s['from'])} −{s['relationship']}→ {_md_escape(s['to'])} | "
                       f"{s['event_uid']} ({_md_escape(s['description'])}) | {s['source_file']}#{s['source_row']} | "
                       f"{s['basis']} ({s['rule']}) | {s['suspicion']} |")
        out += [""] + [f"- {r}" for r in hyp["reasons"]] + [""]
    ch = inc.get("channels")
    if ch:
        out += ["## Multichannel corroboration", "", ch["summary"], "",
                "| Entity | " + " | ".join(ch["labels"][c] for c in ch["channels"]) + " |",
                "|---|" + "---|" * len(ch["channels"])]
        for r in ch["rows"]:
            cells = [str(r["cells"][c]["count"]) if r["cells"][c]["state"] == "evidence"
                     else ("silent" if r["cells"][c]["state"] == "silent" else "-") for c in ch["channels"]]
            out.append(f"| {_md_escape(r['entity'])} | " + " | ".join(cells) + " |")
        out += [""] + [f"- {_md_escape(x)}" for x in ch["silent_observations"] + ch["single_channel_entities"]] + [""]
        if hyp and hyp.get("channels"):
            out += [f"Attack-path hypothesis: {hyp['channels']['summary']}", ""]
    out += ["## Alerts", "", "| Time | Rule | ATT&CK | Severity | Disposition |", "|---|---|---|---|---|"]
    for a in inc["alerts"]:
        out.append(f"| {a['timestamp']} | {_md_escape(a['rule'])} | {a['technique'] or '-'} | {a['severity']} | {a['disposition']} |")
    out += ["", "## Correlation links", ""]
    out += [f"- **{l['rule']}** {l['a']} ↔ {l['b']}: {_md_escape(l['detail'])}" for l in inc["correlation_links"]] or ["- (single signal)"]
    out += ["", "## Timeline", "", "| Time (UTC) | Source | Seed | Description |", "|---|---|---|---|"]
    for t in inc["timeline"]:
        out.append(f"| {t['timestamp']} | {t['source_system']} | {'●' if t['seed'] else ''} | {_md_escape(t['description'])} |")
    out += ["", "## Evidence files", "", "| File | Source system | SHA-256 |", "|---|---|---|"]
    for f in rep["source_files"]:
        out.append(f"| {f['file_name']} | {f['source_system']} | `{f['sha256']}` |")
    out += ["", f"*{rep['hash_limitation']}*", ""]
    return "\n".join(out)


def to_html(rep: dict) -> str:
    md = to_markdown(rep)
    inc = rep["incident"]
    rows = "".join(
        f"<tr><td>{html.escape(t['timestamp'])}</td><td>{html.escape(t['source_system'])}</td>"
        f"<td>{'●' if t['seed'] else ''}</td><td>{html.escape(t['description'])}</td></tr>" for t in inc["timeline"])
    breakdown = "".join(
        f"<tr><td>{html.escape(b['label'])}</td><td>{b['value']}</td><td>{b['weight']}</td><td>{b['contribution']}</td>"
        f"<td>{html.escape(b['explanation'])}</td></tr>" for b in inc["breakdown"])
    path = ""
    if inc.get("hypothesis"):
        steps = "".join(
            f"<tr><td>{html.escape(s['timestamp'])}</td><td>{html.escape(s['from'])} &rarr; {html.escape(s['relationship'])} &rarr; "
            f"{html.escape(s['to'])}</td><td>{html.escape(s['event_uid'])}<br><small>{html.escape(s['description'])}</small></td>"
            f"<td>{html.escape(str(s['source_file']))}#{s['source_row']}</td><td>{s['basis']}</td><td>{s['suspicion']}</td></tr>"
            for s in inc["hypothesis"]["steps"])
        path = (f"<h2>Attack-path hypothesis</h2><p><code>{html.escape(' → '.join(inc['hypothesis']['nodes']))}</code></p>"
                f"<table><tr><th>Time (UTC)</th><th>Step</th><th>Evidence</th><th>Record</th><th>Basis</th><th>Suspicion</th></tr>{steps}</table>")
    channels = ""
    ch = inc.get("channels")
    if ch:
        head = "".join(f"<th>{html.escape(ch['labels'][c])}</th>" for c in ch["channels"])
        body = "".join(
            "<tr><td>" + html.escape(r["entity"]) + "</td>" + "".join(
                f"<td>{r['cells'][c]['count'] if r['cells'][c]['state'] == 'evidence' else ('silent' if r['cells'][c]['state'] == 'silent' else '&mdash;')}</td>"
                for c in ch["channels"]) + "</tr>" for r in ch["rows"])
        channels = (f"<h2>Multichannel corroboration</h2><p>{html.escape(ch['summary'])}</p>"
                    f"<table><tr><th>Entity</th>{head}</tr>{body}</table>")
    files = "".join(f"<tr><td>{html.escape(f['file_name'])}</td><td>{html.escape(str(f['source_system']))}</td><td><code>{f['sha256']}</code></td></tr>"
                    for f in rep["source_files"])
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(inc['id'])} · AttackGraph Lens report</title>
<style>body{{font:14px/1.5 system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#1b1f24}}
table{{border-collapse:collapse;width:100%;margin:.5rem 0 1.5rem}}td,th{{border:1px solid #d0d7de;padding:4px 8px;text-align:left;vertical-align:top}}
th{{background:#f3f4f6}}code{{font-size:12px;word-break:break-all}}.note{{background:#fff8e1;padding:.6rem .8rem;border-left:3px solid #d29922}}
.badge{{display:inline-block;padding:2px 8px;border-radius:4px;background:#1b1f24;color:#fff}}</style></head><body>
<h1>{html.escape(inc['id'])}: {html.escape(inc['title'])}</h1>
<p><span class="badge">{html.escape(inc['priority'])} · {inc['score']}/100</span> &nbsp; {html.escape(inc['start'])} &rarr; {html.escape(inc['end'])}</p>
<p class="note">{html.escape(DISCLAIMER)}</p>
<ul>{''.join(f'<li>{html.escape(x)}</li>' for x in inc['explanation'])}</ul>
<h2>Priority breakdown</h2><table><tr><th>Component</th><th>Value</th><th>Weight</th><th>Contribution</th><th>Basis</th></tr>{breakdown}</table>
{path}
{channels}
<h2>Timeline</h2><table><tr><th>Time (UTC)</th><th>Source</th><th>Seed</th><th>Description</th></tr>{rows}</table>
<h2>Evidence files</h2><table><tr><th>File</th><th>Source</th><th>SHA-256</th></tr>{files}</table>
<p class="note">{html.escape(rep['hash_limitation'])}</p>
<details><summary>Markdown version</summary><pre>{html.escape(md)}</pre></details>
</body></html>"""


def to_json(rep: dict) -> str:
    return json.dumps(rep, indent=2, default=str)
